package com.yuegang.zhihui.training.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.training.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;@Configuration(proxyBeanMethods=false)class TrainingConfiguration{@Bean TrainingProgressService trainingProgressService(DataSource d){return new TrainingProgressService(d);}@Bean TrainingQuizService trainingQuizService(DataSource d,ObjectMapper o){return new TrainingQuizService(d,o);}@Bean TrainingAssignmentService trainingAssignmentService(DataSource d){return new TrainingAssignmentService(d);}@Bean TrainingUserResolver trainingUserResolver(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new TrainingUserResolver(k);}finally{Arrays.fill(k,(byte)0);}}}
